<script lang="ts">
 import {onMount} from 'svelte';import {locale,t} from '$lib/i18n';
 let matches=$state<any>(null),scanning=$state(false);let enabled=$state(false),url=$state(''),key=$state(''),configured=$state(false),message=$state(''),busy=$state(false);
 async function load(){const r=await fetch('/api/v1/settings');if(!r.ok)return;const fields=(await r.json()).fields;enabled=fields.find((f:any)=>f.key==='emby.enabled')?.value??false;url=fields.find((f:any)=>f.key==='emby.url')?.value??'';configured=fields.find((f:any)=>f.key==='emby.api_key')?.configured??false;const mr=await fetch('/api/v1/media-controls/emby/matches');if(mr.ok)matches=await mr.json();}
 async function save(){busy=true;try{const r=await fetch('/api/v1/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({values:{'emby.enabled':enabled,'emby.url':url,'emby.api_key':key}})});if(!r.ok)throw Error('Emby settings could not be saved.');key='';message='Emby settings saved.';await load();}catch(e){message=(e as Error).message;}finally{busy=false;}}
 async function test(){busy=true;try{const r=await fetch('/api/v1/media-controls/emby/test',{method:'POST'});if(!r.ok)throw Error('Emby connection failed. Check address and API key.');message='Emby connection successful.';}catch(e){message=(e as Error).message;}finally{busy=false;}}
 async function scan(){scanning=true;message='';try{const r=await fetch('/api/v1/media-controls/emby/matches',{method:'POST'});if(!r.ok)throw Error('Emby library matching failed; existing matches were retained.');matches=await r.json();message='Emby library matching completed.';}catch(e){message=(e as Error).message;}finally{scanning=false;}}
 onMount(load);
</script>
<section class="space-y-4 rounded-2xl border bg-card p-5"><h2 class="text-xl font-semibold">Emby</h2><p class="text-sm text-muted-foreground">{t($locale,'Read-only availability checks using a server API key. No user accounts or playback history are read. Completion notifications wait for Emby confirmation.')}</p><label class="flex min-h-11 items-center gap-3"><input type="checkbox" bind:checked={enabled}/>{t($locale,'Verify availability in Emby')}</label><label class="block text-sm">{t($locale,'Emby server URL')}<input type="url" bind:value={url} placeholder="http://emby:8096" class="mt-1 min-h-11 w-full rounded-lg border bg-background px-3"/></label><label class="block text-sm">{t($locale,'Emby API key')}<input type="password" autocomplete="new-password" bind:value={key} placeholder={configured?t($locale,'Saved — leave empty to keep'):''} class="mt-1 min-h-11 w-full rounded-lg border bg-background px-3"/></label><div class="flex flex-wrap gap-3"><button disabled={busy} onclick={save} class="min-h-11 rounded-lg bg-primary px-4 text-primary-foreground">{t($locale,'Save')}</button><button disabled={busy} onclick={test} class="min-h-11 rounded-lg border px-4">{t($locale,'Test connection')}</button></div>{#if message}<p role="status">{t($locale,message)}</p>{/if}</section>

<section class="mt-4 space-y-4 rounded-2xl border bg-card p-5"><div class="flex flex-wrap items-center justify-between gap-3"><h2 class="text-xl font-semibold">{t($locale,'Library matching')}</h2><button disabled={scanning||busy||!enabled} onclick={scan} class="min-h-11 rounded-lg border px-4">{t($locale,scanning?'Matching…':'Match Emby library')}</button></div><p class="text-sm text-muted-foreground">{t($locale,'Matches use TMDB, TVDB and IMDb IDs, followed by episode IDs or season and episode numbers. Conflicting IDs are not matched automatically.')}</p>{#if matches?.checked_at}<p class="text-xs text-muted-foreground">{new Date(matches.checked_at).toLocaleString($locale)}</p><div class="grid grid-cols-2 gap-3 sm:grid-cols-4">{#each ['movie','show','season','episode'] as kind}<div class="rounded-xl bg-muted p-3"><span class="text-sm">{t($locale,({movie:'Movies',show:'Series',season:'Seasons',episode:'Episodes'} as Record<string,string>)[kind]??kind)}</span><strong class="mt-1 block text-lg">{matches.counts[kind].matched} / {matches.counts[kind].matched+matches.counts[kind].unmatched}</strong><span class="text-xs text-muted-foreground">{t($locale,'matched')}</span></div>{/each}</div><details class="rounded-xl border p-3"><summary class="min-h-11 cursor-pointer">{t($locale,'Matching details')}</summary><div class="max-h-96 space-y-2 overflow-y-auto">{#each matches.items as item}<div class="flex items-center justify-between gap-3 border-t py-2 text-sm"><a class="min-w-0 break-words underline" href={'/web/dashboard/'+(item.kind==='movie'?'movies/':'tv/')+item.media_id}>{item.details.title}</a><span>{t($locale,item.status==='matched'?'Matched':'Not matched')}</span></div>{/each}</div></details>{/if}</section>
